@Test
public void testNullToleration() {
    System.setProperty(PROP_KEY, "false");
    // loadSystemProperties can only override an existing key in the properties bag.  We should get an empty bag back
    Properties props = WinkSystemProperties.loadSystemProperties(null);
    assertTrue("expected empty properties bag", props.isEmpty());
}

@Test
public void testEmptyValue() {
    Properties startProps = new Properties();
    startProps.put(PROP_KEY, "");
    System.setProperty(PROP_KEY, "false");
    // loadSystemProperties can override an existing key in the properties bag when the value is empty
    Properties props = WinkSystemProperties.loadSystemProperties(startProps);
    assertEquals("expected non-null \"" + PROP_KEY + "\" property to be \"false\"", "false", props.getProperty(PROP_KEY));
}

@Test
public void testGetSystemProperties() throws Exception {
    // empty
    Properties startProps = new Properties();
    System.setProperty(PROP_KEY, "false");
    // loadSystemProperties can only override an existing key in the properties bag.  We should get an empty bag back
    Properties props = WinkSystemProperties.loadSystemProperties(startProps);
    assertTrue("expected empty properties bag", props.isEmpty());
}

@Test
public void testPropsOverride() throws Exception {
    Properties startProps = new Properties();
    startProps.setProperty(PROP_KEY, "true");
    System.setProperty(PROP_KEY, "false");
    // make sure the system property does NOT override what's already in the bag.  We should get an empty bag back
    Properties props = WinkSystemProperties.loadSystemProperties(startProps);
    assertTrue("expected empty properties bag", props.isEmpty());
}

@Test
public void testMessageReader() throws IOException {
    // Entity Input Stream
    ByteArrayInputStream bais = new ByteArrayInputStream(message.getBytes());
    // Entity Stream to be read with DataSourceProvider
    DataSourceProvider dsp = new DataSourceProvider();
    DataSourceProvider.ByteArrayDataSource bads = new DataSourceProvider.ByteArrayDataSource(bais, "text/plain");
    // Check if readable - assert true
    assertTrue(dsp.isReadable(DataSource.class, null, null, null));
    assertTrue(dsp.isReadable(Object.class, null, null, null));
    // Check if readable - assert false
    assertFalse(dsp.isReadable(DataSourceProvider.ByteArrayDataSource.class, null, null, null));
    assertFalse(" Reading to String.class is not supported", dsp.isReadable(String.class, null, null, null));
    DataSource ds = null;
    try {
        // Read Entity
        ds = dsp.readFrom(null, null, null, MediaType.WILDCARD_TYPE, null, bads.getInputStream());
    } catch (IOException e) {
        assertFalse(" Failed to read Entity", true);
    }
    InputStream inputStream = null;
    byte[] buf = new byte[1024];
    int read = 0;
    try {
        inputStream = ds.getInputStream();
        read = inputStream.read(buf);
    } catch (IOException e) {
        assertFalse(" Failed to read Entity", true);
    }
    assertEquals(message, new String(buf, 0, read));
}

@Test
public void testMessageWriter() throws IOException {
    // Entity Data Source
    ByteArrayInputStream bais = new ByteArrayInputStream(message.getBytes());
    DataSourceProvider.ByteArrayDataSource bads = new DataSourceProvider.ByteArrayDataSource(bais, "text/plain");
    // Entity Stream to be read with DataSourceProvider
    DataSourceProvider dsp = new DataSourceProvider();
    // Check if writable - assert true
    assertTrue(dsp.isWriteable(DataSourceProvider.ByteArrayDataSource.class, null, null, null));
    // Check if writable - assert false
    assertFalse(" Writting from String.class is not supported", dsp.isWriteable(String.class, null, null, null));
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    try {
        dsp.writeTo(bads, null, null, null, MediaType.WILDCARD_TYPE, null, baos);
    } catch (IOException e) {
        assertFalse(" Failed to write Entity", true);
    }
    assertEquals(message, new String(baos.toByteArray()));
}

@Test
public void testFileProvider() throws Exception {
    String s = "tttttttttttttttttttttttttttttttttttttttttttttttttttttttttttttt";
    byte[] ba = s.getBytes();
    ByteArrayInputStream bais = new ByteArrayInputStream(ba);
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    // write Buffer 2 file
    assertTrue(fileProvider.isWriteable(File.class, null, null, MediaType.MULTIPART_FORM_DATA_TYPE));
    File f = fileProvider.readFrom(File.class, null, null, MediaType.APPLICATION_SVG_XML_TYPE, null, bais);
    // read File 2 Buffer
    assertTrue(fileProvider.isReadable(File.class, null, null, null));
    fileProvider.writeTo(f, null, null, null, null, null, baos);
    byte[] after = baos.toByteArray();
    // check the same
    assertEquals(ba.length, after.length);
    // check Size
    long size = fileProvider.getSize(f, null, null, null, null);
    assertEquals(size, after.length);
    // try to return serialize Dir
    File dir = File.createTempFile("aaa", "bbb");
    dir.delete();
    dir.mkdir();
    boolean exceptionWasThrown = false;
    try {
        fileProvider.writeTo(dir, null, null, null, null, null, baos);
    } catch (WebApplicationException e) {
        exceptionWasThrown = true;
    }
    assertTrue(exceptionWasThrown);
    int i = 0;
    i++;
}

