@Test
public void testFromStringEmpty() {
    AcceptCharset charset = acceptCharsetDelegate.fromString("");
    assertFalse(charset.isAnyCharsetAllowed());
    assertEquals(Collections.singletonList("ISO-8859-1"), charset.getAcceptableCharsets());
    assertEquals(Collections.EMPTY_LIST, charset.getBannedCharsets());
}

@Test
public void testFromStringUTF8Only() {
    AcceptCharset charset = acceptCharsetDelegate.fromString("utf-8");
    assertFalse(charset.isAnyCharsetAllowed());
    // see HTTP Accept-Char set
    assertEquals(Arrays.asList(new String[] { "ISO-8859-1", "utf-8" }), charset.getAcceptableCharsets());
    assertEquals(Collections.EMPTY_LIST, charset.getBannedCharsets());
}

@Test
public void testFromStringUTF8AndWildcard() {
    AcceptCharset charset = acceptCharsetDelegate.fromString("utf-8,*");
    assertTrue(charset.isAnyCharsetAllowed());
    assertEquals(Arrays.asList(new String[] { "utf-8" }), charset.getAcceptableCharsets());
    // note that any charset allowed means ISO-8859-1 is part of wildcard,
    // see HTTP spec
    assertEquals(Collections.EMPTY_LIST, charset.getBannedCharsets());
}

@Test
public void testFromStringUTF8WithQuality() {
    AcceptCharset charset = acceptCharsetDelegate.fromString("utf-8;q=0.8");
    assertFalse(charset.isAnyCharsetAllowed());
    assertEquals(Arrays.asList(new String[] { "ISO-8859-1", "utf-8" }), charset.getAcceptableCharsets());
    assertEquals(Arrays.asList(new AcceptCharset.ValuedCharset[] { new AcceptCharset.ValuedCharset(1.0, "ISO-8859-1"), new AcceptCharset.ValuedCharset(0.8, "utf-8") }), charset.getValuedCharsets());
    assertEquals(Collections.EMPTY_LIST, charset.getBannedCharsets());
}

@Test
public void testFromStringUTF8WithQualityAndWildcardWithQuality() {
    AcceptCharset charset = acceptCharsetDelegate.fromString("utf-8;q=0.8, *;q=0.4");
    assertTrue(charset.isAnyCharsetAllowed());
    assertEquals(Arrays.asList(new String[] { "utf-8" }), charset.getAcceptableCharsets());
    assertEquals(Arrays.asList(new AcceptCharset.ValuedCharset[] { new AcceptCharset.ValuedCharset(0.8, "utf-8"), new AcceptCharset.ValuedCharset(0.4, null) }), charset.getValuedCharsets());
    // note that any charset allowed means ISO-8859-1 is part of wildcard,
    // see HTTP spec
    assertEquals(Collections.EMPTY_LIST, charset.getBannedCharsets());
}

@Test
public void testSerializeCacheControlHeader() {
    RuntimeDelegate rd = RuntimeDelegate.getInstance();
    HeaderDelegate<CacheControl> cacheControlHeaderDelegate = rd.createHeaderDelegate(CacheControl.class);
    if (cacheControlHeaderDelegate == null) {
        fail("CacheControl header delegate is not regestered in RuntimeDelegateImpl");
    }
    String expectedCacheControlHeader = "private=\"privateField1\", " + "no-cache=\"noCachefield1, noCachefield2\", " + "no-store, " + "no-transform, " + "must-revalidate, " + "proxy-revalidate, " + "max-age=21600, " + "s-maxage=3000, " + "extension=value, " + "extension3, " + "extension2=\"value with space\"";
    CacheControl cc = new CacheControl();
    cc.setMaxAge(21600);
    cc.setMustRevalidate(true);
    cc.setNoCache(true);
    cc.setNoStore(true);
    cc.setNoTransform(true);
    cc.setPrivate(true);
    cc.setProxyRevalidate(true);
    cc.setSMaxAge(3000);
    cc.getCacheExtension().put("extension", "value");
    cc.getCacheExtension().put("extension2", "value with space");
    cc.getCacheExtension().put("extension3", null);
    cc.getNoCacheFields().add("noCachefield1");
    cc.getNoCacheFields().add("noCachefield2");
    cc.getPrivateFields().add("privateField1");
    String[] cache_out = cacheControlHeaderDelegate.toString(cc).split(",");
    String[] cache_expected = expectedCacheControlHeader.split(",");
    Arrays.sort(cache_expected);
    Arrays.sort(cache_out);
    assertArrayEquals(cache_expected, cache_out);
    // assertEquals(expectedCacheControlHeader,
    // cacheControlHeaderDelegate.toString(cc));
    try {
        cacheControlHeaderDelegate.toString(null);
        fail("CacheControl Header is null - IllegalArgumentException must be thrown");
    } catch (IllegalArgumentException e) {
        // success
    }
}

